# area: narrowing_user
# hypothesis: TypeIs narrows an Any argument to str in the positive branch but leaves it Any in the negative branch, so checkers must not invent a narrower type for the else arm.
from typing import Any, TypeIs, assert_type, reveal_type


def is_str(val: object) -> TypeIs[str]:
    return isinstance(val, str)


def check_obj(v: object) -> int:
    if is_str(v):
        assert_type(v, str)
        return len(v)
    else:
        assert_type(v, object)
        return 0


def check_any(v: Any) -> str:
    if is_str(v):
        reveal_type(v)
        return v
    else:
        reveal_type(v)
        return 'not a str'


print(check_obj('abc'), check_obj(3))
print(check_any('x'), check_any(3))
